/// 内容净化选项
class ContentCleaningOptions {
  /// 繁简转换模式: "none", "t2s"(繁转简), "s2t"(简转繁)
  final String convertMode;

  /// 段落处理模式: "none", "smart"(智能), "force"(强制)
  final String paragraphMode;

  /// 是否清理 HTML 标签
  final bool cleanHtml;

  /// 是否删除广告
  final bool removeAds;

  const ContentCleaningOptions({
    required this.convertMode,
    required this.paragraphMode,
    required this.cleanHtml,
    required this.removeAds,
  });

  static Future<ContentCleaningOptions> default_() => RustLib.instance.api.crateApiContentCleaningOptionsDefault();

  @override
  int get hashCode => convertMode.hashCode ^ paragraphMode.hashCode ^ cleanHtml.hashCode ^ removeAds.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ContentCleaningOptions &&
          runtimeType == other.runtimeType &&
          convertMode == other.convertMode &&
          paragraphMode == other.paragraphMode &&
          cleanHtml == other.cleanHtml &&
          removeAds == other.removeAds;
}

